import{_ as n,C as r,o as c,c as s,j as t,a,E as o,a5 as l}from"./chunks/framework.Dep_XxFZ.js";const P=JSON.parse('{"title":"瀑布流","description":"","frontmatter":{},"headers":[],"relativePath":"components/masonry.md","filePath":"components/masonry.md","lastUpdated":1787185306000}'),h={name:"components/masonry.md"},u={id:"瀑布流",tabindex:"-1"};function m(p,e,b,q,x,f){const i=r("Badge"),d=r("XhDemo");return c(),s("div",null,[t("h1",u,[e[0]||(e[0]=a("瀑布流 ",-1)),o(i,{type:"info",text:"masonry"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#瀑布流","aria-label":'Permalink to "瀑布流 <Badge type="info" text="masonry" />"'},"​",-1))]),e[3]||(e[3]=l('<p>等宽不等高的一批项，按最短列优先落进若干列，列数可随容器宽度换档。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>图片墙、卡片流：每一项宽度一致、高度由内容决定，希望底边尽量齐平。</li><li>摘要列表：文字长短不一，不想被强行拉成等高的格子。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>每一项高度一致，或需要跨列跨行：用<a href="./grid">栅格</a>，它是二维规则网格，还能跨列与错列。</li><li>只想让一排东西之间留白：用<a href="./flex">弹性布局</a>。</li><li>上万条数据要滚动：瀑布流会把每一项都渲出来并逐一量高，改用<a href="./virtualizer">虚拟滚动</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>两种落格策略：缺省最短列优先，底边最齐；<code>sequential</code> 打开后按文档序逐列填，读起来是「先走完左列，再走下一列」。</li><li>列数可写成断点对象 <code>{ base, sm, md, lg, xl }</code>，档位名与栅格同一套。</li><li>落格算法是一个不碰 DOM 的纯函数，量高度归适配器；同一批高度在两个适配器上算出同一副版面。</li><li>两个适配器的作者侧写法不同，最终 DOM 一致：Vue 侧只写内容，列的盒子与每一项的盒子都由组件铺；Web Components 侧元素不生成结构，列与项都要作者写进标记，元素只负责把项搬进对应的列。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>等宽不等高的项按最短列优先落进三列，底边尽量齐平</p>',10)),o(d,{src:"masonry/01-basic"}),e[4]||(e[4]=t("h3",{id:"逐档列数",tabindex:"-1"},[a("逐档列数 "),t("a",{class:"header-anchor",href:"#逐档列数","aria-label":'Permalink to "逐档列数"'},"​")],-1)),e[5]||(e[5]=t("p",null,"列数写成断点对象，按容器自身的宽度换档：窄栏一列，宽到 md 两列，宽到 lg 四列",-1)),o(d,{src:"masonry/02-columns"}),e[6]||(e[6]=t("h3",{id:"间距档位",tabindex:"-1"},[a("间距档位 "),t("a",{class:"header-anchor",href:"#间距档位","aria-label":'Permalink to "间距档位"'},"​")],-1)),e[7]||(e[7]=t("p",null,"gap 一档管两处：列与列之间、同一列里项与项之间，留白始终对齐",-1)),o(d,{src:"masonry/03-gap"}),e[8]||(e[8]=t("h3",{id:"逐列填",tabindex:"-1"},[a("逐列填 "),t("a",{class:"header-anchor",href:"#逐列填","aria-label":'Permalink to "逐列填"'},"​")],-1)),e[9]||(e[9]=t("p",null,"打开 sequential 后项按文档序成段落进各列，读起来是「先走完左列，再走下一列」",-1)),o(d,{src:"masonry/04-sequential"}),e[10]||(e[10]=t("h3",{id:"动态增删",tabindex:"-1"},[a("动态增删 "),t("a",{class:"header-anchor",href:"#动态增删","aria-label":'Permalink to "动态增删"'},"​")],-1)),e[11]||(e[11]=t("p",null,"项增删后重新量高、重新落格；新项排在末尾，摘掉一项后其余项会补位",-1)),o(d,{src:"masonry/05-dynamic"}),e[12]||(e[12]=l('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-masonry&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhMasonry</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/masonry.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;masonry&quot;</code>：<strong><code>root</code></strong> · <strong><code>column</code></strong> · <code>item</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>columns</code></td><td><code>MasonryColumns</code></td><td></td><td>分几列，不写按三列。也收断点对象 <code>{ base, sm, md, lg, xl }</code>，逐档写各自的列数， 没写的档沿用比它窄的那一档。换档看的是容器自身的宽度，不是视口宽度。</td></tr><tr><td><code>gap</code></td><td><code>MasonryGap</code></td><td></td><td>列与列、项与项之间的间距档位：xs / sm / md / lg / xl，不写则不留间距。档位换算成多少由皮肤定。</td></tr><tr><td><code>sequential</code></td><td><code>boolean</code></td><td></td><td>按文档序逐列填：项成段落进各列，读起来仍是「先走完左列，再走下一列」。 不写则最短列优先，视觉上更齐平，但相邻的两项未必挨着。</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getColumnProps</code></td><td><code>(props: MasonryColumnProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: MasonryItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><ul><li>落格会<strong>物理重排 DOM</strong>：两个适配器都把项挪进列里，所以朗读序与 Tab 序自此等于列序——先走完第 0 列，再走下一列。作者数组里的第 2 项很可能要等第 5 项念完才轮到。</li><li>顺序有意义的内容（步骤、排行榜、时间线）请打开 <code>sequential</code>：项按文档序成段落进各列，段内保持作者写的先后，朗读与 Tab 只在换列处跳一次。</li><li>根上不写 <code>role</code>，容器只管排布。里面装的若是一份语义列表，请由作者自己在项里写出对应的语义。</li><li>项里若有可聚焦的控件，重排会把焦点连节点一起搬走；浏览器不为节点移动派 <code>focusout</code>，读屏用户会突然失去落点。需要焦点稳定请改用<a href="./grid">栅格</a>。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/masonry.css</code> 按部件选择：<code>[data-scope=&quot;masonry&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-gap</code></td><td>props.gap</td></tr><tr><td><code>root</code></td><td><code>data-sequential</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>column</code></td><td><code>data-index</code></td><td>String(column.index)</td></tr><tr><td><code>item</code></td><td><code>data-column</code></td><td>String(item.column)</td></tr><tr><td><code>item</code></td><td><code>data-index</code></td><td>String(item.index)</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-masonry-gap</code></p><h2 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h2><ul><li>换档看的是<strong>容器自身的宽度</strong>，不是视口宽度：窄栏里的瀑布流不会因为窗口宽就分成三列。</li><li>断点对象没写 <code>base</code> 时按缺省的三列起步，<strong>不像栅格那样回落到一列</strong>：<code>{ md: 4 }</code> 读作「窄时三列、md 起四列」。要窄时一列请显式写 <code>base: 1</code>。</li><li>容器改宽、项的内容改高，都会重新量并重排；浏览器不支持 <code>ResizeObserver</code> 时不再跟随尺寸变化——Vue 适配器停在挂载与每次更新那一刻量到的高度，Web Components 元素则每次接线时量一遍。</li></ul><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><ul><li>列的先后跟着书写方向走：<code>dir=&quot;rtl&quot;</code> 下第 0 列在最右边，列内仍自上而下。</li><li>项与列之间的间距全部走逻辑属性，不需要为 RTL 另写规则。</li></ul><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>每一项里放<a href="./card">卡片</a>或<a href="./image">图片</a>最常见；图片请写明宽高比，否则加载完成前量到的高度是 0，加载完成后会重排一次。</li><li>一项里放<a href="./skeleton">骨架屏</a>占位时，请让骨架的高度接近真实内容，减少一次大的重排。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>重排会把某一项挪进另一列。Vue 适配器上这一项会被重新挂载，项里别放不可重建的状态（正在播放的视频、没提交的输入）。</li><li>摘掉一项后焦点会掉回 <code>&lt;body&gt;</code>，键盘与读屏用户每摘一次就丢一次位置。组件不接管这件事，删除按钮请自己把焦点交给下一项或列表容器。</li><li>图片一律写 <code>width</code> / <code>height</code> 或 <code>aspect-ratio</code>：不写就要等图片加载完才量得到真实高度，一屏图片会引起一整轮重排。</li><li>Web Components 侧请按最宽那一档需要的列数写足 <code>column</code> 节点：元素不生成结构，手上没有的列变不出来，当前档位用不上的那几列会被自动收起。<code>column</code> 必须是空容器，项由元素搬进去。</li><li>Web Components 侧项的先后取「首次见到的顺序」：静态标记就是作者写的顺序，运行期新增的项排在末尾。要把新项插到中间，请整块重建这批项。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用 CSS 的 <code>columns</code> 代替本组件：那是竖向分栏，阅读顺序是「一列读到底再读下一列」，与最短列优先的落格顺序对不上。</li><li>把有先后关系的内容（步骤、排行榜）放进最短列优先的瀑布流：作者写的先后不再是朗读与 Tab 的先后。要保住顺序请打开 <code>sequential</code>。</li><li>项与项之间用外边距拉开距离：间距由 <code>gap</code> 档位统一给，自己写外边距会让列内与列间的留白对不齐。</li></ul>',33))])}const y=n(h,[["render",m]]);export{P as __pageData,y as default};
